import{_ as e,o as s,c as t,a2 as i}from"./chunks/framework.ORnkkB96.js";const u=JSON.parse('{"title":"Instalación","description":"","frontmatter":{},"headers":[],"relativePath":"es/instalacao.md","filePath":"es/instalacao.md","lastUpdated":1792519643000}'),o={name:"es/instalacao.md"};function n(r,a,l,d,c,h){return s(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="instalacion" tabindex="-1">Instalación <a class="header-anchor" href="#instalacion" aria-label="Permalink to &quot;Instalación&quot;">​</a></h1><p>Vision.AI corre en contenedores con <strong>Docker Swarm</strong>. El instalador oficial descarga la versión correcta, la descomprime y levanta los quince servicios de una vez.</p><blockquote><p>La guía completa, por sistema operativo, está en el repositorio del instalador: <strong><a href="https://github.com/bortolottic/vision.ai.installer" target="_blank" rel="noreferrer">vision.ai.installer</a></strong>. Esta página es el resumen.</p></blockquote><h2 id="requisitos" tabindex="-1">Requisitos <a class="header-anchor" href="#requisitos" aria-label="Permalink to &quot;Requisitos&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Recurso</th><th>Mínimo</th><th>Recomendado</th></tr></thead><tbody><tr><td>RAM</td><td>8 GB</td><td>16 GB</td></tr><tr><td>CPU</td><td>4 núcleos</td><td>8 núcleos</td></tr><tr><td>Disco</td><td>40 GB libres</td><td>100 GB libres</td></tr></tbody></table><p>La inferencia y el entrenamiento corren en <strong>CPU</strong> por defecto. Para tiempo real con varias cámaras, use un nodo con <strong>GPU NVIDIA</strong> y el modo <code>--gpu</code> (ver <a href="/vision.ai.installer/es/operacao#gpu">Operación</a>).</p><h2 id="puertos" tabindex="-1">Puertos <a class="header-anchor" href="#puertos" aria-label="Permalink to &quot;Puertos&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Puerto</th><th>Para qué sirve</th></tr></thead><tbody><tr><td><strong>9080</strong></td><td>La plataforma en el navegador</td></tr><tr><td>8189/UDP</td><td>WebRTC (video en vivo)</td></tr><tr><td>3433</td><td>Base de datos (solo inspección; se puede cerrar)</td></tr><tr><td>443</td><td>HTTPS, en modo <code>--ssl</code></td></tr></tbody></table><h2 id="pasos" tabindex="-1">Pasos <a class="header-anchor" href="#pasos" aria-label="Permalink to &quot;Pasos&quot;">​</a></h2><ol><li>Instale Docker y active Swarm:<div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> swarm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span></span></code></pre></div></li><li>Ejecute el instalador:<div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://raw.githubusercontent.com/bortolottic/vision.ai.installer/refs/heads/main/install.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> bash</span></span></code></pre></div></li><li>Abra <code>http://localhost:9080</code> (o la dirección del servidor en el puerto 9080).</li></ol><p>Para una versión específica, agregue la etiqueta:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://raw.githubusercontent.com/bortolottic/vision.ai.installer/refs/heads/main/install.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> bash</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> V1.0.0.0</span></span></code></pre></div><h2 id="despues-de-instalar" tabindex="-1">Después de instalar <a class="header-anchor" href="#despues-de-instalar" aria-label="Permalink to &quot;Después de instalar&quot;">​</a></h2><ul><li><strong>Secretos:</strong> se generan automáticamente en la primera instalación y se escriben en <code>/tmp/vision-ai/vision-ai/.env.production</code>. <strong>Respalde ese archivo.</strong></li><li><strong>Dirección pública:</strong> en un servidor, ajuste <code>VISION_PUBLIC_URL</code> y <code>VISION_WEBRTC_HOST</code> en <code>.env.production</code> y ejecute <code>./deploy_production.sh</code> de nuevo.</li></ul><p>Los detalles de GPU, HTTPS y respaldo están en <a href="/vision.ai.installer/es/operacao">Operación</a>.</p>',15)])])}const k=e(o,[["render",n]]);export{u as __pageData,k as default};
